1	//! Authentication middleware trait for the actix runtime server.
2	//!
3	//! The [`AuthLayer`] trait is the single extension point for request authentication.
4	//! The server calls [`AuthLayer::authenticate`] before dispatching any request to an
5	//! agent handler. Implementations decide whether a request is allowed and, on success,
6	//! may attach identity information to [`actix_web::HttpRequest::extensions_mut`] for
7	//! downstream use.
8	
9	use actix_web::HttpRequest;
10	use async_trait::async_trait;
11	
12	use crate::error::AuthRejection;
13	
14	/// Middleware hook called by the server on every inbound request before routing.
15	///
16	/// Implement this trait to plug in any authentication scheme — API keys, JWTs,
17	/// mutual TLS, etc. — without touching the agent or transport code.
18	///
19	/// # Identity handoff
20	///
21	/// On a successful authentication the implementation **may** insert an opaque
22	/// identity value into `req.extensions_mut()`:
23	///
24	/// ```ignore
25	/// req.extensions_mut().insert(MyIdentity { user_id: ... });
26	/// ```
27	///
28	/// The server's [`ContextProvider`](crate::ContextProvider) receives the same
29	/// `&HttpRequest` when it builds the context value for a run, so identity values
30	/// placed here are available to context-building logic and, through the context, to
31	/// agent handlers. This is the documented auth→context bridge.
32	///
33	/// On failure the implementation returns an [`AuthRejection`] carrying the HTTP
34	/// status code (typically `401 Unauthorized` or `403 Forbidden`) and a
35	/// human-readable message. The server converts this into a JSON error response
36	/// and does **not** forward the request to any handler.
37	///
38	/// # `RefCell` borrows
39	///
40	/// actix request extensions are `RefCell`-backed — drop the `RefMut` from
41	/// `extensions_mut()` before any `.await`, and do not read `extensions()` while a
42	/// mutable borrow is live, or it panics at runtime.
43	///
44	/// # Thread safety
45	///
46	/// Implementations must be `Send + Sync` because the server holds a single
47	/// shared instance behind an `Arc` and calls `authenticate` concurrently from
48	/// multiple Tokio tasks.
49	///
50	/// # `?Send` futures
51	///
52	/// `actix_web::HttpRequest` wraps an `Rc` internally and is therefore `!Sync`
53	/// (so `&HttpRequest` is `!Send`). Any implementation that actually reads from
54	/// `req` — the common case — captures a `!Send` reference in its future, so
55	/// this trait is declared `#[async_trait(?Send)]`: the returned future is not
56	/// required to be `Send`. This matches actix-web's own execution model, where
57	/// request-bound futures are polled to completion on the worker thread that
58	/// received the request and never migrate across threads.
59	#[async_trait(?Send)]
60	pub trait AuthLayer: Send + Sync {
61	    /// Inspect and optionally mutate the request `req` to authenticate the
62	    /// caller.
63	    ///
64	    /// - Return `Ok(())` to allow the request to proceed. Optionally insert an
65	    ///   identity value into `req.extensions_mut()` for downstream consumers.
66	    /// - Return `Err(`[`AuthRejection`]`)` to reject the request. The server
67	    ///   will respond with the status code and message from the rejection.
68	    async fn authenticate(&self, req: &HttpRequest) -> Result<(), AuthRejection>;
69	}
70	
71	#[cfg(test)]
72	mod tests {
73	    use actix_web::{http::StatusCode, test::TestRequest, HttpMessage};
74	
75	    use crate::error::AuthRejection;
76	
77	    use super::AuthLayer;
78	
79	    /// A minimal identity value an auth impl may insert into `req.extensions_mut()`.
80	    #[derive(Clone)]
81	    struct Identity(String);
82	
83	    /// Mock auth layer used by the test suite only.
84	    struct MockAuthLayer;
85	
86	    #[async_trait::async_trait(?Send)]
87	    impl AuthLayer for MockAuthLayer {
88	        async fn authenticate(&self, req: &actix_web::HttpRequest) -> Result<(), AuthRejection> {
89	            let token = match req.headers().get("authorization") {
90	                None => {
91	                    return Err(AuthRejection {
92	                        status: StatusCode::UNAUTHORIZED,
93	                        message: "missing authorization header".into(),
94	                    })
95	                }
96	                Some(value) => value.to_str().unwrap_or("").to_owned(),
97	            };
98	            req.extensions_mut().insert(Identity(token));
99	            Ok(())
100	        }
101	    }
102	
103	    #[tokio::test]
104	    async fn reject_when_header_missing() {
105	        let layer = MockAuthLayer;
106	        let req = TestRequest::default().to_http_request();
107	        let err = layer.authenticate(&req).await.unwrap_err();
108	        assert_eq!(err.status, StatusCode::UNAUTHORIZED);
109	    }
110	
111	    #[tokio::test]
112	    async fn inserts_identity_on_success() {
113	        let layer = MockAuthLayer;
114	        let req = TestRequest::default()
115	            .insert_header(("authorization", "Bearer tok123"))
116	            .to_http_request();
117	        layer.authenticate(&req).await.unwrap();
118	        let identity = req.extensions().get::<Identity>().unwrap().clone();
119	        assert_eq!(identity.0, "Bearer tok123");
120	    }
121	}
